from __future__ import annotations

from fastapi import Request
from fastapi.responses import HTMLResponse


HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>§wyrlz Live Pages</title><style>body{margin:0;background:#050914;color:#eef7ff;font-family:system-ui}.wrap{max-width:1100px;margin:auto;padding:16px}.card{background:#0a1425;border:1px solid #284768;border-radius:16px;padding:14px;margin:10px 0}.row{display:flex;gap:8px;flex-wrap:wrap}.row>*{flex:1;min-width:160px}input,textarea,button,select{font:inherit}input,select,textarea{width:100%;box-sizing:border-box;background:#050c17;color:#fff;border:1px solid #315475;border-radius:10px;padding:10px}textarea{min-height:48vh;font-family:ui-monospace,monospace}button{background:#142943;color:#fff;border:1px solid #37618a;border-radius:10px;padding:10px 12px;font-weight:700}.badge{display:inline-block;border:1px solid #315475;border-radius:999px;padding:7px 10px;margin:4px 6px 4px 0}.ok{color:#59f1a7;border-color:#2a7357}.bad{color:#ff8798;border-color:#8c3a49}.muted{color:#91aac4}.entry{padding:9px;border-top:1px solid #203650}.entry a{color:#70eaff}pre{white-space:pre-wrap;overflow-wrap:anywhere}</style></head><body><div class="wrap"><h1>§WYRLZ LIVE PAGE MANAGER</h1><p class="muted">Admin unlocks the manager. GitHub write credentials stay server-side and are never echoed back to the browser.</p><div class="card"><div class="row"><input id="admin" type="password" placeholder="Admin token"><button onclick="setAdmin()">SET ADMIN</button><button onclick="syncNow()">SYNC DEV → RUNTIME</button></div><div id="state" style="margin-top:10px"><span class="badge">ADMIN · LOCKED</span><span class="badge">GITHUB WRITE · UNKNOWN</span><span class="badge">SOURCE · dev</span></div><pre id="out">Enter Admin token, then SET ADMIN.</pre></div><div class="card"><select id="pick" onchange="loadPage()"></select><div class="row" style="margin:8px 0"><button onclick="loadPage()">LOAD RUNTIME</button><button onclick="saveRuntime()">SAVE RUNTIME</button><button onclick="pushDev()">PUSH RUNTIME → DEV</button><button onclick="openPage()">OPEN PAGE</button></div><textarea id="editor" spellcheck="false"></textarea></div><div class="card"><b>Pages</b><div id="pages"></div></div></div><script>let token=sessionStorage.getItem('swrlzAdminToken')||'';admin.value=token;let items=[];const headers=()=>({'x-swrlz-admin-token':token});async function call(action,key='',body=null){let r=await fetch('/api/pages?'+new URLSearchParams({action,key}),{method:'POST',headers:headers(),body,cache:'no-store'}),j=await r.json();if(!r.ok)throw Error(JSON.stringify(j));return j}function show(x){out.textContent=typeof x==='string'?x:JSON.stringify(x,null,2)}function badges(adminOk,ghOk,branch='dev'){state.innerHTML=`<span class="badge ${adminOk?'ok':'bad'}">ADMIN · ${adminOk?'AUTHENTICATED':'LOCKED'}</span><span class="badge ${ghOk?'ok':'bad'}">GITHUB WRITE · ${ghOk?'CONFIGURED':'NOT CONFIGURED'}</span><span class="badge ok">SOURCE · ${branch}</span>`}async function setAdmin(){token=admin.value.trim();sessionStorage.setItem('swrlzAdminToken',token);await refresh()}async function refresh(){try{let j=await call('list');items=j.pages||[];badges(true,!!j.githubWriteConfigured,j.branch||'dev');pick.innerHTML=items.map(x=>`<option value="${x.key}">${x.key} · ${x.source}</option>`).join('');pages.innerHTML=items.map(x=>`<div class="entry"><b>${x.key}</b> · <a href="${x.url}">${x.url}</a><br><span class="muted">${x.source} → ${x.runtime}</span></div>`).join('');show({ok:j.ok,branch:j.branch,githubWriteConfigured:j.githubWriteConfigured,pageCount:items.length});if(items.length)await loadPage(false)}catch(e){badges(false,false);show('FAILED '+e.message)}}async function syncNow(){try{let j=await call('sync');show(j);await refresh()}catch(e){show('FAILED '+e.message)}}async function loadPage(updateOut=true){try{let j=await call('read',pick.value);editor.value=j.content||'';if(updateOut)show(j.meta)}catch(e){show('FAILED '+e.message)}}async function saveRuntime(){try{show(await call('save-runtime',pick.value,new Blob([editor.value])));await refresh()}catch(e){show('FAILED '+e.message)}}async function pushDev(){if(!confirm('Push this runtime file to dev source-of-truth?'))return;try{show(await call('push-dev',pick.value));await refresh()}catch(e){show('FAILED '+e.message)}}function openPage(){let x=items.find(x=>x.key===pick.value);if(x)window.open(x.url,'_blank')}if(token)refresh();</script></body></html>'''


def install(server) -> None:
    @server.app.middleware("http")
    async def page_manager_ui(request: Request, call_next):
        if request.method == "GET" and request.url.path.rstrip("/") == "/api/pages" and not request.query_params:
            return HTMLResponse(HTML, headers={"Cache-Control": "no-store, max-age=0", "X-SWRLZ-Page-Manager-UI": "2"})
        return await call_next(request)

    server.CAPABILITIES["page-manager-credential-status"] = {
        "kind": "admin-ui",
        "ready": True,
        "githubSecretExposed": False,
        "statusFrom": "POST /api/pages?action=list",
    }
